            bOutShtLoseICNeedSetErrBin=false;                                   //JerryYang 20170609 (wei) for JSCC 清除旗標
            bIndexDropICNeedSetErrBin=false;                                    //JerryYang 20220923 : index arm drop error設ERROR BIN
