        Z1_ErrorCount=MOT[MTestZ1].GetGali_Pr_Result();
        Z2_ErrorCount=MOT[MTestZ2].GetGali_Pr_Result();
        Y2_ErrorCount=MOT[MTestY2].GetGali_Pr_Result();

